companions=[{'forGoalId':ids[0],'id':None,'titleDe':'Rutherford-Streubefunde für das Kern-Hülle-Modell deuten','titleEn':'Interpret Rutherford scattering evidence for the nuclear model','descriptionDe':'Die lernende Person kann aus vorgegebenen Befunden des Rutherford-Streuexperiments einen kleinen positiv geladenen, massereichen Atomkern und einen überwiegend leeren Atomraum begründen.','descriptionEn':'The learner can use supplied observations of Rutherford scattering to justify a small, positively charged, massive atomic nucleus and mostly empty atomic space.','prospectiveRequires':['9b5d6326-d27c-4ece-8c72-debda705464a'],'parentId':'1e803ef8-fc76-493d-85c5-de877cd38fda','sourceGoalId':'he-chem-seki-10-1-b01-a01-20d6b173','stage':'SekI HE10; BY8NTG partial clause','limits':['no inference of neutron existence from scattering','no quantitative scattering law','no own hazardous experiment','no automatic ID adoption']},
{'forGoalId':ids[2],'id':None,'titleDe':'Verwendungen ausgewählter Alkalimetallverbindungen begründen','titleEn':'Justify uses of selected alkali-metal compounds','descriptionDe':'Die lernende Person kann die Verwendung einer ausgewählten Alkalimetallverbindung mit deren passenden Stoffeigenschaften begründen und sie dabei vom elementaren Alkalimetall unterscheiden.','descriptionEn':'The learner can justify a use of a selected alkali-metal compound through its relevant material properties, distinguishing it from the elemental alkali metal.','prospectiveRequires':['950c73c6-4ed1-488a-9267-1142e95e0055'],'parentId':'254f7a85-17fa-57c7-8447-28ec05f3c2cf','sourceGoalId':'he-chem-seki-9-2-b01-a01-28c1edb7','stage':'SekI HE9 normative clause; prerequisite timing HOLD','limits':['compound identity is a constraint on the same use justification','no full compound catalogue','no automatic BY applicability','no automatic ID adoption']}]
retained=[{'goalId':ids[0],'candidateTitleDe':'Atombausteine im Kern-Hülle-Modell darstellen','candidateTitleEn':'Represent atomic particles in the nuclear model','candidateDescriptionDe':'Die lernende Person kann den Aufbau von Atomen mit dem Kern-Hülle-Modell darstellen und Protonen, Neutronen sowie Elektronen nach ihrem Ort und ihrer Ladung fachlich einordnen.','candidateDescriptionEn':'The learner can represent atomic structure using the nuclear model and correctly classify protons, neutrons and electrons by location and charge.','sourceGoalId':'he-chem-seki-10-1-b01-a02-a20c7e8a','allocationStatus':'proposed retain current ID; not adopted'}, {'goalId':ids[2],'candidateTitleDe':'Eigenschaften elementarer Alkalimetalle charakterisieren','candidateTitleEn':'Characterize properties of elemental alkali metals','candidateDescriptionDe':'Die lernende Person kann ausgewählte elementare Alkalimetalle anhand ihrer typischen Stoffeigenschaften charakterisieren und eine Verwendung des Metalls mit einer passenden Eigenschaft begründen.','candidateDescriptionEn':'The learner can characterize selected elemental alkali metals by their typical material properties and justify a use of the metal through a relevant property.','sourceGoalId':'he-chem-seki-9-2-b01-a01-28c1edb7','allocationStatus':'proposed retain current ID; not adopted','givensQualifier':'A supplied elemental-metal use must actually involve the metal, e.g. sodium as a heat-transfer medium; lithium-ion batteries belong to compound context.'}]
